{
  "name": "noto-mode",
  "version": "1.0.19",
  "description": "Approves the permission prompts auto mode would skip (read-only actions, edits in the project, a classifier for the rest) and explains every prompt that still reaches you.",
  "author": {
    "name": "Eric Fisher"
  },
  "license": "MIT",
  "keywords": [
    "permissions",
    "auto-mode",
    "auto-approve",
    "classifier",
    "prompts",
    "hooks",
    "mod",
    "workflow",
    "quality-of-life"
  ],
  "userConfig": {
    "classifier": {
      "type": "boolean",
      "title": "Use a model classifier",
      "description": "Judge gray-area calls (most shell commands, MCP tools) with a small model, as auto mode does. Off: those calls prompt you as before.",
      "default": true
    },
    "model": {
      "type": "string",
      "title": "Classifier model",
      "description": "An alias (haiku, sonnet) or a full model id for the classifier.",
      "default": "haiku"
    },
    "timeoutMs": {
      "type": "number",
      "title": "Classifier timeout (ms)",
      "description": "How long one classifier call may take before the prompt is shown instead.",
      "default": 20000
    },
    "quiet": {
      "type": "boolean",
      "title": "Quiet",
      "description": "No toasts when the classifier approves a call. The status line and /noto-mode still report.",
      "default": false
    }
  }
}
